import React, { createContext, useState, useContext, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useModal } from './ModalContext';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);

  const navigate = useNavigate();
  const { showModal } = useModal();

  // 🔄 Загружаем данные при загрузке приложения
  useEffect(() => {
    const loadStoredData = () => {
      try {
        // 1. Проверяем, есть ли сохраненный пользователь
        const storedUser = localStorage.getItem('luna_user');
        const storedToken = localStorage.getItem('luna_token');

        if (storedUser && storedToken) {
          // Проверяем срок действия токена (7 дней)
          try {
            const tokenData = JSON.parse(atob(storedToken.split('.')[1]));
            const currentTime = Math.floor(Date.now() / 1000);

            if (tokenData.exp > currentTime) {
              // Токен действителен
              setUser(JSON.parse(storedUser));
              setToken(storedToken);
            } else {
              // Токен истёк
              localStorage.removeItem('luna_user');
              localStorage.removeItem('luna_token');
            }
          } catch (error) {
            console.error('Error parsing token:', error);
            clearStoredData();
          }
        }

        // 2. Загружаем корзину
        const storedCart = localStorage.getItem('luna_cart');
        if (storedCart) {
          try {
            setCart(JSON.parse(storedCart));
          } catch (error) {
            console.error('Error parsing cart:', error);
            localStorage.removeItem('luna_cart');
          }
        }

        // 3. Загружаем избранное
        const storedFavorites = localStorage.getItem('luna_favorites');
        if (storedFavorites) {
          try {
            setFavorites(JSON.parse(storedFavorites));
          } catch (error) {
            console.error('Error parsing favorites:', error);
            localStorage.removeItem('luna_favorites');
          }
        }

        // 4. Загружаем заказы
        const storedOrders = localStorage.getItem('luna_orders');
        if (storedOrders) {
          try {
            setOrders(JSON.parse(storedOrders));
          } catch (error) {
            console.error('Error parsing orders:', error);
            localStorage.removeItem('luna_orders');
          }
        }

      } catch (error) {
        console.error('Error loading stored data:', error);
        clearStoredData();
      } finally {
        setLoading(false);
      }
    };

    loadStoredData();
  }, []);

  // 🔄 Сохраняем данные при изменении
  useEffect(() => {
    if (user) {
      localStorage.setItem('luna_user', JSON.stringify(user));
    }
  }, [user]);

  useEffect(() => {
    if (token) {
      localStorage.setItem('luna_token', token);
    }
  }, [token]);

  useEffect(() => {
    localStorage.setItem('luna_cart', JSON.stringify(cart));
