      const existingUsers = JSON.parse(localStorage.getItem('luna_users') || '[]');

      // Проверка на существующий email
      const userExists = existingUsers.some(u => u.email === email);
      if (userExists) {
        throw new Error('Пользователь с таким email уже зарегистрирован');
      }

      // Проверка на существующее имя пользователя
      const usernameExists = existingUsers.some(u => u.username === username);
      if (usernameExists) {
        throw new Error('Это имя пользователя уже занято');
      }

      // Проверка пароля
      if (password.length < 6) {
        throw new Error('Пароль должен содержать минимум 6 символов');
      }

      // Создаём нового пользователя
      const newUser = {
        id: Date.now().toString(),
        username,
        email,
        password: password, // ⚠️ В реальном приложении нужно хэшировать пароль!
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
