    setOrders(prevOrders =>
      prevOrders.map(order =>
        order.id === orderId ? { ...order, status: 'cancelled' } : order
      )
    );
  };

  // 🔄 Обновление данных пользователя
  const updateUser = (updatedData) => {
    // Обновляем в состоянии
    setUser(prev => {
      const newUser = { ...prev, ...updatedData, updatedAt: new Date().toISOString() };
      return newUser;
    });

    // Обновляем в "базе данных"
    const existingUsers = JSON.parse(localStorage.getItem('luna_users') || '[]');
    const updatedUsers = existingUsers.map(u => 
      u.id === user.id ? { ...u, ...updatedData, updatedAt: new Date().toISOString() } : u
    );
    localStorage.setItem('luna_users', JSON.stringify(updatedUsers));
  };

  // 🔄 Очистка localStorage
  const clearStoredData = () => {
    localStorage.removeItem('luna_user');
    localStorage.removeItem('luna_token');
    localStorage.removeItem('luna_cart');
    localStorage.removeItem('luna_favorites');
    localStorage.removeItem('luna_orders');
  };

  // 🔄 Проверка авторизации
  const isAuthenticated = !!user && !!token;

  const value = {
    // Основные данные
    user,
    token,
    loading,
    isAuthenticated,

    // Аутентификация
    register,
    login,
    logout,
    updateUser,

    // Корзина
    cart,
    addToCart,
    removeFromCart,
    updateCartQuantity,
    clearCart,

    // Избранное
    favorites,
    addToFavorites,
    removeFromFavorites,

    // Заказы
    orders,
    createOrder,
    cancelOrder,

    // Вспомогательные
    generateToken,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
